import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.achievements.*;import idle.core.save.*;import java.util.*;import java.nio.file.*;
public class ProbeDark{public static void main(String[]args)throws Exception{Game g=new Game(SaveCodec.read(Files.readString(Path.of(args[0]))).state(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,Achievements.DEFAULT,new Random(1));System.out.println("pps="+g.productionPerSecond()+" expl="+g.state().explosions()+" dark="+g.state().darkMatter()+" earned="+g.darkMatterEarned()+" attempts="+g.completedChallenges());for(DarkUpgrade d:g.darkUpgrades())if(g.darkLevelOf(d.id())>0)System.out.printf(" %s=%d (%s)\n",d.id(),g.darkLevelOf(d.id()),d.branch());System.out.printf("NEXT density=%s priming=%s mass=%s size=%s\n",g.darkCostOf("dark_density"),g.darkCostOf("dark_priming"),g.darkCostOf("dark_mass"),g.state().darkMatterSize());}}
